export type TransportConfig = {
  /**
   * Тип сокета ('http' или 'unix_dgram'), по умолчанию 'unix_dgram'
   */
  socketType: 'unix_dgram';
  /**
   * Путь до сокета, по умолчанию '/errorbooster'
   * @default '/errorbooster'
   */
  socketPath: string;
} | {
  /**
   * Тип сокета ('http' или 'unix_dgram'), по умолчанию 'unix_dgram'
   */
  socketType: 'http';
  /**
   * Хост сокета, по умолчанию 'localhost'
   * @default 'localhost'
   */
  socketHost?: string;
  /**
   * Порт сокета, по умолчанию '12522'
   * @default 12522
   */
  socketPort?: number;
  /**
   * Путь до сокета, по умолчанию '/errorbooster'
   * @default '/errorbooster'
   */
  socketPath?: string;
  /**
   * Максимальное количество одновременных сокетов к unified agent,
   * по умолчанию '8'
   */
  maxTotalSockets?: number;
};
export type BufferFromLike = Parameters<typeof Buffer.from>[0];
export function getTransport(config: TransportConfig): (data: BufferFromLike) => void;
